{"content": "{
  "main_characters": [
    {
      "name": "沈卓衡",
      "role": "protagonist",
      "identity": "法租界公董局特聘法医官，留法归国，师承前任首席法医顾敬堂",
      "traits": ["理性至上", "嗅觉过敏（职业病）", "执拗偏执", "孤僻但重情", "对未知有病态好奇心"],
      "overt_motivation": "破解三起密室溺毙案，找出凶手，维护法医学尊严",
      "covert_motivation": "证明一切异常现象都有科学解释——这源于少年时目睹师父顾敬堂临终前的'失常'行为（喃喃念诵规则），需要用理性为师父正名",
      "secret_fear": "害怕自己终有一天也会像师父一样'失去理性'——害怕科学无法解释的东西真的存在",
      "misperception_of_other": "认为韩兆麟是装神弄鬼的江湖骗子，认为苏碧城只是爱好猎奇的花瓶记者",
      "hidden_connection": "师父顾敬堂20年前调查过同类案件，留下的笔记中包含规则抄本——沈卓衡少年时读过这些笔记，对'异常尸检'的执着由此而来。他在案发现场无意识地用手帕捂鼻屏息（嗅觉过敏），恰好契合第六条原始含义，被凶手误认为'被选中的信徒'"
    },
    {
      "name": "苏碧城",
      "role": "deuteragonist",
      "identity": "《申报》副刊特约记者，精通英法双语，专跑租界奇闻",
      "traits": ["聪慧锐利", "胆大心细", "善于伪装", "有正义感但功利", "隐藏的语言学天赋"],
      "overt_motivation": "追踪密室命案写出轰动报道，凭此升任正式编辑",
      "covert_motivation": "她的父亲苏鸿儒（前法租界公董局华人档案管理员）在20年前的一场'意外'中死亡，死因同样是'无水溺毙'——她怀疑父亲的死与通灵会有关，借采访之名暗中调查父亲真正死因",
      "secret_fear": "害怕发现父亲不是'无辜受害者'，而是规则传播链中的一环——父亲可能主动参与了通灵会的某些行为",
      "misperception_of_other": "认为沈卓衡是冷血的解剖机器，不关心死者背后的'人'；后来发现他对师父的深情",
      "hidden_connection": "她父亲苏鸿儒与沈卓衡的师父顾敬堂是同时代人——苏鸿儒管理的法租界档案室正是1842年Hartley手册的存放地，顾敬堂当年调查案件时从苏鸿儒处获得了手册线索。两家的悲剧有同一个源头"
    }
  ],
  "supporting_characters": [
    {
      "name": "韩兆麟",
      "function": "反转点",
      "identity": "上海通灵会'玄光社'创始人兼主持，前清秀才出身，精通中西玄学",
      "description": "表面是装神弄鬼的江湖术士，实则是最早意识到七条规则'不对劲'的人。他创建通灵会是为了监控和限制规则的传播，试图将规则控制在小圈子内。第一次反转中成为第四具尸体——他的死证明凶手不是他，而是另有其人。韩兆麟留下的密码遗书成为第二幕的关键线索"
    },
    {
      "name": "赵宝琛",
